const D = { energy:.6, scale:1, density:.5, speed:1, hue:30, phason:.4, bevel:.6, x:.5, y:.5, style:'inlay', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const cl = (v,a,b) => v<a?a:(v>b?b:v);
const u = Math.min(width, height);
const sd = P.seed|0;
const fr = i => { const s = Math.sin(i*127.1 + sd*311.7)*43758.5453; return s - Math.floor(s); };
const sty = P.style, H = ((P.hue%360)+360)%360, en = cl(P.energy,0,1);
const sp = .25 + .75*P.speed;
const lift = .55 + .45*K.intensity;
const bass = (S.b = (S.b||0)*.84 + (A.bass||0)*.16);
const trb  = (S.tb = (S.tb||0)*.87 + (A.treble||0)*.13);

if (S.pt == null || K.t < S.pt) S.pt = K.t;
const dt = cl(K.t - S.pt, 0, .1); S.pt = K.t;

// ---- two Fibonacci chains, crossed --------------------------------------
// Each axis is the staircase of Z^2 under a line of slope 1/phi: gaps come in
// exactly two lengths L and S with L/S = phi, in the Sturmian order (never SS,
// never LLL). Crossing two of them cuts the plane into FOUR rectangle types --
// LL, LS, SL, SS -- laid out quasiperiodically: the 2D Fibonacci quasilattice.
const TH = 0.6180339887498949, C2 = 1 + TH*TH;
const pos = (m, r) => (m + TH*Math.floor(m*TH + r)) / C2;
const isL = (m, r) => (Math.floor((m+1)*TH + r) - Math.floor(m*TH + r)) === 1;

S.gx = (S.gx||0) + dt*sp*(.070 + .052*Math.sin(K.t*.039));
S.gy = (S.gy||0) + dt*sp*(.041 + .052*Math.cos(K.t*.047+1.6));
S.px = (S.px||0) + dt*sp*(.03 + .30*cl(P.phason,0,1));
S.py = (S.py||0) + dt*sp*(.03 + .30*cl(P.phason,0,1))*.71;

const zoom = 1 + .07*Math.sin(K.t*.053*sp) + .04*Math.sin(K.t*.131*sp+2.1);
const gu = Math.max(u*.125*cl(P.scale,.6,2.2), Math.max(width,height)/26) * zoom;
const rhoX = 1.7 + S.px, rhoY = 4.3 + S.py*1.13;
const qx = (TH*rhoX - TH*.5)/C2, qy = (TH*rhoY - TH*.5)/C2;

const ax = cl(P.x,.25,.75)*width, ay = cl(P.y,.25,.75)*height;
const nX = Math.ceil(Math.max(ax, width-ax)/gu) + 2, nY = Math.ceil(Math.max(ay, height-ay)/gu) + 2;
const m0 = Math.round(-qx - S.gx), n0 = Math.round(-qy - S.gy);

// ---- styles ---------------------------------------------------------------
const glow = (sty==='xray');
function grd(){
  if (sty==='blueprint') return [212, 64, 40];
  if (sty==='riso')      return [44, 9, 93];
  if (glow)              return [(H+190)%360, 58, 5];
  if (sty==='concrete')  return [(H+180)%360, 4, 58];
  return [(H+8)%360, 32, 12];
}
// tone per rectangle type: 0=SS 1=SL 2=LS 3=LL
function typeCol(ty, lam, wv){
  const v = (.32 + .66*lam)*(.6+.5*en) + wv*.45;
  if (sty==='blueprint') return [ 206 + ty*4, 30 + ty*8, cl(26 + 50*v + ty*5, 6, 94) ];
  if (sty==='riso')      return [ [352,352,205,205][ty], cl(38 + 18*ty,8,88), cl(56 + 44*v, 12, 100) ];
  if (glow)              return [ (H + 120 + ty*48)%360, 42, cl(14 + 86*v, 2, 100) ];
  if (sty==='concrete')  return [ (H+180)%360, cl(2 + ty*2,0,12), cl(30 + 52*v + ty*4, 4, 92) ];
  return [ (H + 2 + ty*16)%360, cl(50 - 10*ty, 6, 74), cl(26 + 52*v + ty*7, 4, 96) ];
}

const gc = grd(); noStroke(); background(gc[0], gc[1], gc[2]);
const lang = K.t*.071*sp + .5*Math.sin(K.t*.0313+1.4);
const lgx = Math.cos(lang), lgy = Math.sin(lang);
const wavT = K.t*(.5 + .9*sp) + .8*Math.sin(K.t*.041+.6);
const bv = cl(P.bevel,0,1);
const dens = cl(P.density,0,1);

push(); translate(ax, ay);
strokeJoin(MITER);
const jw = (u/900)*(.6 + 2.0*en);
let drawn = 0;

for (let m=m0-nX; m<=m0+nX; m++){
  const x0 = (pos(m,rhoX) + S.gx)*gu, x1 = (pos(m+1,rhoX) + S.gx)*gu;
  if (x1 < -Math.max(ax,width-ax)-gu || x0 > Math.max(ax,width-ax)+gu) continue;
  const LX = isL(m, rhoX);
  for (let n=n0-nY; n<=n0+nY; n++){
    const y0 = (pos(n,rhoY) + S.gy)*gu, y1 = (pos(n+1,rhoY) + S.gy)*gu;
    if (y1 < -Math.max(ay,height-ay)-gu || y0 > Math.max(ay,height-ay)+gu) continue;
    const LY = isL(n, rhoY);
    const ty = (LX?2:0) + (LY?1:0);
    const w = x1-x0, h = y1-y0, cxm = x0+w*.5, cym = y0+h*.5;
    const dl = Math.hypot(cxm,cym) || 1;
    const lam = cl(.5 + .5*((cxm/dl)*lgx + (cym/dl)*lgy), 0, 1);
    // a wave of state change crossing the quasilattice
    const wv = Math.pow(Math.max(0, Math.sin((cxm+cym)/gu*.5 - wavT)), 4) * (.6+.5*bass) * lift;
    const jit = fr(m*13.1 + n*29.7);
    const c = typeCol(ty, lam*(.75+.35*jit), wv);
    if (glow) {
      blendMode(ADD);
      noStroke(); fill(c[0], c[1], c[2], cl(6 + 14*lam + 22*wv, 2, 44));
      rect(x0, y0, w, h);
      blendMode(BLEND);
      noFill(); stroke(c[0], c[1], cl(c[2]*(.5+.6*trb+.4*wv),0,100), cl(28 + 54*lam, 10, 92));
      strokeWeight(jw*(.6+.8*wv+.4)); rect(x0, y0, w, h);
    } else {
      noStroke(); fill(c[0], c[1], c[2], 100); rect(x0, y0, w, h);
      // bevel: a lit top-left and a sunk bottom-right -> inlaid panels, not flat fill
      if (bv > .04) {
        strokeWeight(jw*(.6 + 1.4*bv));
        stroke(c[0], cl(c[1]*.6,0,100), cl(c[2]*(1 + .5*bv),0,100), 46 + 30*bv);
        line(x0, y0, x1, y0); line(x0, y0, x0, y1);
        stroke(c[0], cl(c[1]*1.2,0,100), cl(c[2]*(1 - .55*bv),0,100), 46 + 30*bv);
        line(x0, y1, x1, y1); line(x1, y0, x1, y1);
      }
      // each of the four types keeps its own hatch discipline
      if (dens > .06 && Math.min(w,h) > 13) {
        stroke(c[0], cl(c[1]+14,0,100), cl(c[2]*.55,0,100), 16 + 40*dens);
        strokeWeight(jw*.42);
        const nh = 2 + Math.round(dens*3);
        for (let k2=1;k2<=nh;k2++){
          const f = k2/(nh+1);
          if (ty===0) { /* SS: left plain -> the quiet cell */ }
          else if (ty===1) line(x0, y0+h*f, x1, y0+h*f);
          else if (ty===2) line(x0+w*f, y0, x0+w*f, y1);
          else { line(x0, y0+h*f, x1, y0+h*f); line(x0+w*f, y0, x0+w*f, y1); }
        }
      }
      noFill(); stroke(gc[0], cl(gc[1]*1.2,0,100), cl(gc[2]*(.5+.5*(1-en)),0,100), 80);
      strokeWeight(jw*.8); rect(x0, y0, w, h);
    }
    drawn++;
    if (drawn > 460) break;
  }
  if (drawn > 460) break;
}
pop();

// ---- moving chiaroscuro ---------------------------------------------------
const lw2 = 180, lh2 = cl(Math.round(180*height/Math.max(1,width)), 60, 340);
if (!S.lg || S.lgk !== lw2+'x'+lh2) { S.lg = createGraphics(lw2, lh2); S.lg.colorMode(HSB,360,100,100,100); S.lgk = lw2+'x'+lh2; }
const L = S.lg;
L.push(); L.noStroke(); L.blendMode(BLEND);
L.background(0, 0, 100 - (18 + 28*en));
L.blendMode(ADD);
const plx = (.5 + .30*Math.cos(lang))*lw2, ply = (.5 + .26*Math.sin(lang*1.27+.9))*lh2;
for (let i=0;i<9;i++){
  const q=i/8, rr=Math.max(lw2,lh2)*(1.26-q*.98);
  L.fill(0,0,100, (6.5 + 7.5*en + 5*bass)*(.26+.74*q*q));
  L.ellipse(plx, ply, rr*2, rr*2);
}
L.blendMode(BLEND); L.pop();
blendMode(MULTIPLY); noStroke(); image(L, 0, 0, width, height); blendMode(BLEND);

// ---- cached grain ---------------------------------------------------------
const tk = sty+'|'+sd;
if (!S.tex || S.texk !== tk) {
  const tw=420, th=280, t=createGraphics(tw,th);
  t.colorMode(HSB,360,100,100,100); t.background(0,0,100); t.noStroke();
  for (let i=0;i<2200;i++){
    const rr=.4+fr(i*4.61)*1.8;
    t.fill(32, 8, 100-fr(i*7.31)*42, 50);
    t.ellipse(fr(i*2.17)*tw, fr(i*3.91+3.7)*th, rr, rr);
  }
  S.tex = t; S.texk = tk;
}
blendMode(MULTIPLY); noStroke(); image(S.tex, 0, 0, width, height); blendMode(BLEND);

if (P.alpha < 100) { noStroke(); fill(0,0,0, 100 - cl(P.alpha,0,100)); rect(0,0,width,height); }
blendMode(BLEND); drawingContext.shadowBlur = 0;
